package it.polimi.progetto_tiw_js.api.fornitore;

import it.polimi.progetto_tiw_js.api.BaseApiServlet;
import it.polimi.progetto_tiw_js.beans.SKU;
import it.polimi.progetto_tiw_js.dao.SKUDAO;
import jakarta.servlet.ServletException;
import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;

import java.io.IOException;
import java.sql.SQLException;

/**
 * Aggiorna un singolo campo di una SKU tramite inline editing
 * e restituisce il dettaglio aggiornato in JSON.
 */
@WebServlet("/apifornitoreskuaggiorna")
public class AggiornaSKUServlet extends BaseApiServlet {

    private static final long serialVersionUID = 1L;

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        if (!isLogged(req, resp)) return;
        if (!hasRole(req, resp, "FORNITORE")) return;

        req.setCharacterEncoding("UTF-8");

        String idParam = req.getParameter("id");
        String campo = req.getParameter("campo");
        String valore = req.getParameter("valore");

        if (isBlank(idParam) || isBlank(campo) || valore == null) {
            sendError(resp, HttpServletResponse.SC_BAD_REQUEST, "Parametri mancanti");
            return;
        }

        int id;
        try {
            id = Integer.parseInt(idParam.trim());
        } catch (NumberFormatException e) {
            sendError(resp, HttpServletResponse.SC_BAD_REQUEST, "Id non valido");
            return;
        }

        if (id <= 0) {
            sendError(resp, HttpServletResponse.SC_BAD_REQUEST, "Id non valido");
            return;
        }

        try {
            SKUDAO skuDAO = new SKUDAO(conn);
            SKU sku = skuDAO.findById(id);

            if (sku == null) {
                sendError(resp, HttpServletResponse.SC_NOT_FOUND, "SKU non trovata");
                return;
            }

            String campoPulito = campo.trim();

            switch (campoPulito) {
                case "nome" -> {
                    String nome = valore.trim();

                    if (nome.isBlank()) {
                        sendError(resp, HttpServletResponse.SC_BAD_REQUEST,
                                "Il nome non può essere vuoto");
                        return;
                    }

                    skuDAO.updateNome(id, nome);
                }

                case "descrizioneTecnica" -> {
                    String descrizione = valore.trim();

                    if (descrizione.isBlank()) {
                        sendError(resp, HttpServletResponse.SC_BAD_REQUEST,
                                "La descrizione tecnica non può essere vuota");
                        return;
                    }

                    skuDAO.updateDescrizioneTecnica(id, descrizione);
                }

                case "prezzo" -> {
                    double prezzo;

                    try {
                        prezzo = Double.parseDouble(valore.trim());
                    } catch (NumberFormatException e) {
                        sendError(resp, HttpServletResponse.SC_BAD_REQUEST,
                                "Prezzo non valido");
                        return;
                    }

                    if (prezzo < 0) {
                        sendError(resp, HttpServletResponse.SC_BAD_REQUEST,
                                "Il prezzo deve essere maggiore o uguale a 0");
                        return;
                    }

                    skuDAO.updatePrezzo(id, prezzo);
                }

                default -> {
                    sendError(resp, HttpServletResponse.SC_BAD_REQUEST,
                            "Campo non aggiornabile");
                    return;
                }
            }

            SKU skuAggiornata = skuDAO.findById(id);
            sendJson(resp, skuAggiornata);

        } catch (SQLException e) {
            throw new ServletException("Errore durante l'aggiornamento della SKU", e);
        }
    }

    private boolean isBlank(String valore) {
        return valore == null || valore.isBlank();
    }
}

package it.polimi.progetto_tiw_js.api.fornitore;

import it.polimi.progetto_tiw_js.api.BaseApiServlet;
import it.polimi.progetto_tiw_js.beans.SKU;
import it.polimi.progetto_tiw_js.dao.SKUDAO;
import jakarta.servlet.ServletException;
import jakarta.servlet.annotation.MultipartConfig;
import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.Part;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Paths;
import java.sql.SQLException;

/**
 * Aggiorna un singolo campo di una SKU tramite inline editing
 * e restituisce il dettaglio aggiornato in JSON.
 */
@WebServlet("/apifornitoreskuaggiorna")
@MultipartConfig
public class AggiornaSKUServlet extends BaseApiServlet {

    private static final long serialVersionUID = 1L;

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        if (!isLogged(req, resp)) return;
        if (!hasRole(req, resp, "FORNITORE")) return;

        req.setCharacterEncoding("UTF-8");

        boolean multipart = isMultipart(req);

        String idParam = multipart ? leggiCampoTestuale(req, "id") : req.getParameter("id");
        String campo = multipart ? leggiCampoTestuale(req, "campo") : req.getParameter("campo");
        String valore = multipart ? leggiCampoTestuale(req, "valore") : req.getParameter("valore");

        if (isBlank(idParam) || isBlank(campo) || (valore == null && !"fotografia".equalsIgnoreCase(campo))) {
            sendError(resp, HttpServletResponse.SC_BAD_REQUEST, "Parametri mancanti");
            return;
        }

        int id;
        try {
            id = Integer.parseInt(idParam.trim());
        } catch (NumberFormatException e) {
            sendError(resp, HttpServletResponse.SC_BAD_REQUEST, "Id non valido");
            return;
        }

        if (id <= 0) {
            sendError(resp, HttpServletResponse.SC_BAD_REQUEST, "Id non valido");
            return;
        }

        try {
            SKUDAO skuDAO = new SKUDAO(conn);
            SKU sku = skuDAO.findById(id);

            if (sku == null) {
                sendError(resp, HttpServletResponse.SC_NOT_FOUND, "SKU non trovata");
                return;
            }

            String campoPulito = campo.trim();

            switch (campoPulito) {
                case "nome" -> {
                    String nome = valore.trim();

                    if (nome.isBlank()) {
                        sendError(resp, HttpServletResponse.SC_BAD_REQUEST,
                                "Il nome non può essere vuoto");
                        return;
                    }

                    skuDAO.updateNome(id, nome);
                }

                case "descrizioneTecnica" -> {
                    String descrizione = valore.trim();

                    if (descrizione.isBlank()) {
                        sendError(resp, HttpServletResponse.SC_BAD_REQUEST,
                                "La descrizione tecnica non può essere vuota");
                        return;
                    }

                    skuDAO.updateDescrizioneTecnica(id, descrizione);
                }

                case "prezzo" -> {
                    double prezzo;

                    try {
                        prezzo = Double.parseDouble(valore.trim());
                    } catch (NumberFormatException e) {
                        sendError(resp, HttpServletResponse.SC_BAD_REQUEST,
                                "Prezzo non valido");
                        return;
                    }

                    if (prezzo < 0) {
                        sendError(resp, HttpServletResponse.SC_BAD_REQUEST,
                                "Il prezzo deve essere maggiore o uguale a 0");
                        return;
                    }

                    skuDAO.updatePrezzo(id, prezzo);
                }

                case "codice" -> {
                    int codice;

                    try {
                        codice = Integer.parseInt(valore.trim());
                    } catch (NumberFormatException e) {
                        sendError(resp, HttpServletResponse.SC_BAD_REQUEST,
                                "Codice non valido");
                        return;
                    }

                    if (codice < 0) {
                        sendError(resp, HttpServletResponse.SC_BAD_REQUEST,
                                "Il codice deve essere maggiore o uguale a 0");
                        return;
                    }

                    if (skuDAO.existsByCodiceExceptId(codice, id)) {
                        sendError(resp, HttpServletResponse.SC_CONFLICT,
                                "Esiste già una SKU con questo codice");
                        return;
                    }

                    skuDAO.updateCodice(id, codice);
                }

                case "fotografia" -> {
                    if (!multipart) {
                        sendError(resp, HttpServletResponse.SC_BAD_REQUEST,
                                "Upload fotografia non valido");
                        return;
                    }

                    Part fotoPart = req.getPart("fotografia");

                    if (fotoPart == null || fotoPart.getSize() == 0) {
                        sendError(resp, HttpServletResponse.SC_BAD_REQUEST,
                                "Fotografia mancante");
                        return;
                    }

                    String fotografia = salvaFoto(fotoPart);
                    if (fotografia == null) {
                        sendError(resp, HttpServletResponse.SC_INTERNAL_SERVER_ERROR,
                                "Errore durante il salvataggio della fotografia");
                        return;
                    }

                    skuDAO.updateFotografia(id, fotografia);
                }

                default -> {
                    sendError(resp, HttpServletResponse.SC_BAD_REQUEST,
                            "Campo non aggiornabile");
                    return;
                }
            }

            SKU skuAggiornata = skuDAO.findById(id);
            sendJson(resp, skuAggiornata);

        } catch (SQLException e) {
            throw new ServletException("Errore durante l'aggiornamento della SKU", e);
        }
    }

    private boolean isBlank(String valore) {
        return valore == null || valore.isBlank();
    }

    private boolean isMultipart(HttpServletRequest req) {
        String contentType = req.getContentType();
        return contentType != null && contentType.toLowerCase().startsWith("multipart/");
    }

    private String leggiCampoTestuale(HttpServletRequest req, String nomeCampo)
            throws IOException, ServletException {
        Part part = req.getPart(nomeCampo);
        if (part == null) {
            return null;
        }

        byte[] contenuto = part.getInputStream().readAllBytes();
        return new String(contenuto, StandardCharsets.UTF_8);
    }

    private String estraiNomeFile(Part part) {
        String submitted = part.getSubmittedFileName();
        if (submitted == null) {
            return null;
        }

        int slash = submitted.lastIndexOf('/');
        int backslash = submitted.lastIndexOf('\\');
        int indice = Math.max(slash, backslash);

        return (indice >= 0) ? submitted.substring(indice + 1) : submitted;
    }

    private String salvaFoto(Part part) {
        try {
            String nomeOriginale = estraiNomeFile(part);

            if (isBlank(nomeOriginale)) {
                return null;
            }

            String nomePulito = Paths.get(nomeOriginale).getFileName().toString();

            int punto = nomePulito.lastIndexOf('.');
            String estensione = punto >= 0 ? nomePulito.substring(punto) : "";

            String nomeGenerato = "sku_" + System.currentTimeMillis() + estensione;

            String uploadDirPath = getServletContext().getRealPath("/uploads");
            if (uploadDirPath == null) {
                return null;
            }

            File uploadDir = new File(uploadDirPath);
            if (!uploadDir.exists() && !uploadDir.mkdirs()) {
                return null;
            }

            String filePathAssoluto = uploadDir.getAbsolutePath() + File.separator + nomeGenerato;
            part.write(filePathAssoluto);

            return "uploads/" + nomeGenerato;
        } catch (Exception e) {
            return null;
        }
    }
}

package it.polimi.progetto_tiw_js.dao;

import it.polimi.progetto_tiw_js.beans.SKU;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;

public class SKUDAO {

    private final Connection conn;

    public SKUDAO(Connection conn) {
        this.conn = conn;
    }

    // Legge la riga corrente del ResultSet e costruisce il bean SKU.
    private SKU mapRow(ResultSet rs) throws SQLException {
        SKU sku = new SKU();
        sku.setId(rs.getInt("id"));
        sku.setCodice(rs.getInt("codice"));
        sku.setNome(rs.getString("nome"));
        sku.setFotografia(rs.getString("fotografia"));
        sku.setDescrizioneTecnica(rs.getString("descrizione_tecnica"));
        sku.setPrezzo(rs.getDouble("prezzo"));
        return sku;
    }

    // Inserisce una nuova SKU e restituisce l'id generato dal database.
    // Il campo fotografia può essere null se il fornitore non carica alcun file.
    public int createSKU(int codice, String nome, String fotografia,
                         String descrizioneTecnica, double prezzo) throws SQLException {
        String sql = "INSERT INTO sku (codice, nome, fotografia, descrizione_tecnica, prezzo) " +
                "VALUES (?, ?, ?, ?, ?)";

        try (PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
            stmt.setInt(1, codice);
            stmt.setString(2, nome);
            stmt.setString(3, fotografia);
            stmt.setString(4, descrizioneTecnica);
            stmt.setDouble(5, prezzo);
            stmt.executeUpdate();

            try (ResultSet generatedKeys = stmt.getGeneratedKeys()) {
                if (generatedKeys.next()) {
                    return generatedKeys.getInt(1);
                }
            }

            throw new SQLException("Creazione SKU fallita: id non restituito dal database");
        }
    }

    // Restituisce tutte le SKU ordinate per codice decrescente.
    // Questo ordine serve per la lista mostrata nei form del fornitore.
    public List<SKU> findAll() throws SQLException {
        String sql = "SELECT * FROM sku ORDER BY codice DESC";
        List<SKU> result = new ArrayList<>();

        try (PreparedStatement stmt = conn.prepareStatement(sql);
             ResultSet rs = stmt.executeQuery()) {

            while (rs.next()) {
                result.add(mapRow(rs));
            }
        }

        return result;
    }

    // Cerca una SKU tramite chiave primaria.
    // Restituisce null se l'id non esiste.
    public SKU findById(int id) throws SQLException {
        String sql = "SELECT * FROM sku WHERE id = ?";

        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setInt(1, id);

            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) {
                    return mapRow(rs);
                }
            }
        }

        return null;
    }

    // Ricerca case-insensitive su nome e descrizione tecnica.
    // La parola chiave viene cercata anche come match parziale tramite wildcard.
    public List<SKU> searchByKeyword(String keyword) throws SQLException {
        String sql = "SELECT * FROM sku WHERE LOWER(nome) LIKE ? OR LOWER(descrizione_tecnica) LIKE ?";
        String searchPattern = "%" + keyword.toLowerCase() + "%";

        List<SKU> result = new ArrayList<>();

        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, searchPattern);
            stmt.setString(2, searchPattern);

            try (ResultSet rs = stmt.executeQuery()) {
                while (rs.next()) {
                    result.add(mapRow(rs));
                }
            }
        }

        return result;
    }

    // Elimina una SKU tramite id.
    // Prima rimuove le configurazioni che la contengono,
    // poi elimina la SKU vera e propria.
    public void deleteSKU(int id) throws SQLException {
        boolean oldAutoCommit = conn.getAutoCommit();
        conn.setAutoCommit(false);

        try {
            String deleteConfigurazioni = """
                DELETE FROM configurazione
                WHERE id IN (
                    SELECT DISTINCT configurazione_id
                    FROM configurazione_sku
                    WHERE sku_id = ?
                )
                """;

            try (PreparedStatement stmt = conn.prepareStatement(deleteConfigurazioni)) {
                stmt.setInt(1, id);
                stmt.executeUpdate();
            }

            String deleteSku = "DELETE FROM sku WHERE id = ?";
            try (PreparedStatement stmt = conn.prepareStatement(deleteSku)) {
                stmt.setInt(1, id);
                stmt.executeUpdate();
            }

            conn.commit();
        } catch (SQLException e) {
            conn.rollback();
            throw e;
        } finally {
            conn.setAutoCommit(oldAutoCommit);
        }
    }

    // Controlla se esiste già una SKU con il codice indicato.
    // Serve per intercettare il duplicato prima dell'inserimento.
    public boolean existsByCodice(int codice) throws SQLException {
        String sql = "SELECT COUNT(*) FROM sku WHERE codice = ?";

        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setInt(1, codice);

            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) {
                    return rs.getInt(1) > 0;
                }
            }
        }

        return false;
    }

    // Aggiorna il nome della SKU.
    public void updateNome(int id, String nome) throws SQLException {
        String sql = "UPDATE sku SET nome = ? WHERE id = ?";

        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, nome);
            stmt.setInt(2, id);
            stmt.executeUpdate();
        }
    }

    // Aggiorna la descrizione tecnica della SKU.
    public void updateDescrizioneTecnica(int id, String descrizioneTecnica) throws SQLException {
        String sql = "UPDATE sku SET descrizione_tecnica = ? WHERE id = ?";

        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, descrizioneTecnica);
            stmt.setInt(2, id);
            stmt.executeUpdate();
        }
    }

    // Aggiorna il prezzo della SKU.
    public void updatePrezzo(int id, double prezzo) throws SQLException {
        String sql = "UPDATE sku SET prezzo = ? WHERE id = ?";

        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setDouble(1, prezzo);
            stmt.setInt(2, id);
            stmt.executeUpdate();
        }
    }
}

package it.polimi.progetto_tiw_js.dao;

import it.polimi.progetto_tiw_js.beans.SKU;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;

public class SKUDAO {

    private final Connection conn;

    public SKUDAO(Connection conn) {
        this.conn = conn;
    }

    // Legge la riga corrente del ResultSet e costruisce il bean SKU.
    private SKU mapRow(ResultSet rs) throws SQLException {
